def plan_cloudsql_pool(max_instances,workers_per_instance,current_pool,max_connections,reserved_connections):
    values=(max_instances,workers_per_instance,current_pool,max_connections,reserved_connections)
    if any(type(x) is not int for x in values):raise ValueError("all capacity inputs must be integers")
    if max_instances<1 or workers_per_instance<1 or current_pool<1 or max_connections<1 or reserved_connections<0:
        raise ValueError("invalid connection capacity input")
    application_budget=max_connections-reserved_connections
    if application_budget<1:raise ValueError("no application connection budget remains")
    per_worker=application_budget//(max_instances*workers_per_instance)
    if per_worker<1:raise ValueError("instance concurrency exceeds available database connections")
    aggregate=max_instances*workers_per_instance*current_pool
    return {"aggregate_peak_connections":aggregate,"application_budget":application_budget,
        "current_config_fits":aggregate<=application_budget,"recommended_pool_cap_per_worker":min(current_pool,per_worker),
        "action":"bound autoscaled instances and each worker pool together; preserve an explicit administrative reserve; monitor aggregate database connections during scale-out"}
